<template><PageShell title="用户管理" tcode="SU01"><template #actions><el-button type="primary" @click="open()">新建用户</el-button></template><el-card><el-table :data="rows" border stripe><el-table-column prop="username" label="用户名" /><el-table-column prop="realName" label="姓名" /><el-table-column prop="role" label="角色" /><el-table-column prop="enabled" label="状态"><template #default="{row}"><el-switch v-model="row.enabled" @change="save(row)" /></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="open(row)">编辑</el-button><el-button link @click="reset(row)">重置密码</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="visible" title="用户"><el-form :model="form" label-width="80px"><el-form-item label="用户名"><el-input v-model="form.username" :disabled="editing" /></el-form-item><el-form-item label="姓名"><el-input v-model="form.realName" /></el-form-item><el-form-item label="密码" v-if="!editing"><el-input v-model="form.password" show-password /></el-form-item><el-form-item label="角色"><el-select v-model="form.role"><el-option v-for="x in ['ADMIN','MM','FI','SD','PP']" :key="x" :label="x" :value="x" /></el-select></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save(form)">保存</el-button></template></el-dialog></PageShell></template>
<script setup>
import { onMounted, reactive, ref } from 'vue'; import PageShell from '../../components/PageShell.vue'; import { basisApi } from '../../api'; import { ElMessageBox } from 'element-plus'; const rows=ref([]),visible=ref(false),editing=ref(false),form=reactive({});async function load(){rows.value=await basisApi.users()};function open(r){editing.value=!!r;Object.assign(form,r||{username:'',realName:'',password:'admin123',role:'MM',enabled:true});visible.value=true};async function save(r){editing.value?await basisApi.updateUser(r.id,r):await basisApi.createUser(r);visible.value=false;load()};async function reset(r){const x=await ElMessageBox.prompt('输入新密码','重置密码',{inputType:'password'});await basisApi.resetPassword(r.id,{password:x.value});};onMounted(load)
</script>
